def is_palindrome(x: int) -> bool:
    x = str(x)
    return x == x[::-1]

def find_max_palindromic_cube(n: int) -> int:
    ans = 0
    i = 1
    while True:
        cube = i ** 3
        if cube > n:
            break
        if is_palindrome(cube):
            ans = cube
        i += 1
    return ans

n = int(input())
print(find_max_palindromic_cube(n))
